const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.fraud.net', { waitUntil: 'networkidle' });

  // Extract CSS custom properties from :root
  const cssVars = await page.evaluate(() => {
    const styles = getComputedStyle(document.documentElement);
    const vars = {};
    for (const sheet of document.styleSheets) {
      try {
        for (const rule of sheet.cssRules) {
          if (rule.selectorText === ':root' || rule.selectorText === 'html') {
            const text = rule.cssText;
            const matches = text.matchAll(/--([\w-]+):\s*([^;]+);/g);
            for (const m of matches) vars[m[1]] = m[2].trim();
          }
        }
      } catch(e) {}
    }
    return vars;
  });

  // Extract computed styles from key elements
  const elementStyles = await page.evaluate(() => {
    const extract = (sel) => {
      const el = document.querySelector(sel);
      if (!el) return null;
      const s = getComputedStyle(el);
      return {
        color: s.color,
        backgroundColor: s.backgroundColor,
        fontFamily: s.fontFamily,
        fontSize: s.fontSize,
        fontWeight: s.fontWeight,
        lineHeight: s.lineHeight,
      };
    };
    return {
      body: extract('body'),
      h1: extract('h1'),
      h2: extract('h2'),
      h3: extract('h3'),
      p: extract('p'),
      nav: extract('nav'),
      primaryBtn: extract('a.btn, .btn-primary, [class*="button"], a[href*="demo"]'),
      link: extract('a'),
    };
  });

  // Extract all unique colors used on page
  const allColors = await page.evaluate(() => {
    const colors = new Set();
    const allEls = document.querySelectorAll('*');
    for (const el of allEls) {
      const s = getComputedStyle(el);
      ['color','backgroundColor','borderColor','outlineColor'].forEach(prop => {
        const v = s[prop];
        if (v && v !== 'rgba(0, 0, 0, 0)' && v !== 'transparent') colors.add(v);
      });
    }
    return [...colors].slice(0, 40);
  });

  // Extract all font families
  const allFonts = await page.evaluate(() => {
    const fonts = new Set();
    document.querySelectorAll('*').forEach(el => {
      const f = getComputedStyle(el).fontFamily;
      if (f) fonts.add(f);
    });
    return [...fonts];
  });

  // Screenshot homepage
  await page.screenshot({ path: '/tmp/fraudnet-home.png', fullPage: false });

  console.log('=== CSS VARIABLES ===');
  console.log(JSON.stringify(cssVars, null, 2));
  console.log('\n=== ELEMENT STYLES ===');
  console.log(JSON.stringify(elementStyles, null, 2));
  console.log('\n=== ALL COLORS ===');
  console.log(JSON.stringify(allColors, null, 2));
  console.log('\n=== FONTS ===');
  console.log(JSON.stringify([...new Set(allFonts)], null, 2));

  await browser.close();
})();
