  // Viewport-only (above fold)
  await page.screenshot({ path: '/tmp/article-viewport.png', fullPage: false });

  // Scroll to get bottom of article area  
  await page.evaluate(() => window.scrollTo(0, 2000));
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/article-mid.png', fullPage: false });

