  const info = await page.evaluate(() => {
    const toc = document.querySelector('[class*="table-of-contents"], [class*="toc"], aside, .sidebar');
    const relatedBlock = document.querySelector('[class*="related"], [class*="interested"], [class*="more"]');
    const articleBody = document.querySelector('article, [class*="article"], [class*="blog"], main');
    return {
      hasTOC: !!toc,
      tocClass: toc?.className,
      hasRelated: !!relatedBlock,
      relatedClass: relatedBlock?.className,
      bodyClass: articleBody?.className,
      bodyTag: articleBody?.tagName
    };
  });
  console.log('Page structure:', JSON.stringify(info, null, 2));

  await browser.close();
})();
